mapper.select:
select ifnull(sum(storage_stock),0)
from storage_goods_base
where goods_id = #{goodsId}

select mgs.goods_id, mgs.common_id, mgs.storage_stock, mgs.storage_id, si.storage_name from storage_goods_base mgs left join storage_info si on mgs.storage_id = si.storage_id where mgs.shop_id = #{param.shopId}
and mgs.goods_id = #{param.goodsId}
and mgs.storage_id = #{param.storageId}

select mgs.storage_id, si.storage_name, si.storage_province, si.storage_city, si.storage_area, si.storage_address, si.storage_contacts, si.storage_mobile from storage_goods_base mgs left join storage_info si on mgs.storage_id = si.storage_id where mgs.shop_id = #{param.shopId}
#{item}
group by mgs.storage_id

select ifnull(sum(storage_stock),0)
from storage_goods_base
where goods_id = #{goodsId} and storage_id = #{storageId}

select ifnull(sum(storage_stock),0)
from storage_goods_base
where common_id = #{commonId}

select ifnull(sum(storage_stock),0)
from storage_goods_base
where goods_id = #{goodsId}
